// Tests for src/dmd/doc.ts: the unittest blocks of dmd/doc.d (10 §1.2, numbered in source order), the identity
// of the embedded Ddoc theme, and whole-module Ddoc runs through the shim compared with ldc2's HTML.
//
// ORACLES. The theme is pinned against dmd/res/default_ddoc_theme.ddoc in the LDC 1.43.0 tree, the file doc.d:950
// string-imports. A Ddoc run is pinned against the test's expected file tests/dmd/compilable/extra-files/<test>.html
// in the same tree, normalized as compilable/extra-files/ddocAny-postscript.sh normalizes before its diff (every
// line containing `Generated by Ddoc from` dropped, line-ending CRs dropped) and as ddocYear-postscript.sh does
// (`__YEAR__` is the current year); a file written in the OUTPUT_FILES form starts with a `=== <path>` line that
// stands where the page's leading blank line is. For each pinned test, ldmd2 1.43.0 run with the same arguments
// (`-D -Dd<dir> -o- -c`, plus the test's REQUIRED_ARGS) wrote HTML equal to that expected file under the same
// normalization.

import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, describe, expect, test, vi } from "vitest";
import { OutBuffer } from "./common/outbuffer.js";
import { MarkdownLink, MarkdownLinkReferences, escapeDdocString, replaceChar, skipChars, toLowercase } from "./doc.js";
import { default_ddoc_theme } from "./res/default_ddoc_theme.js";
import { ds, dsToJs } from "../dstring.js";

// ORACLE CONSTANT: a checkout of LDC v1.43.0's sources (tests/dmd); set it to yours to run the oracle tests.
const LDC = "/Users/pinver/Projects/Public/ldc-1.43.0";
const COMPILABLE = join(LDC, "tests/dmd/compilable");

describe("doc.d", () => {
    test("unittest#1 skipChars", () => {
        const buf = new OutBuffer();
        const data = "test ---\r\n\r\nend";
        buf.write(ds(data));

        expect(skipChars(buf, 0, ds("-"))).toBe(0);
        expect(skipChars(buf, 4, ds("-"))).toBe(4);
        expect(skipChars(buf, 4, ds(" -"))).toBe(8);
        expect(skipChars(buf, 8, ds("\r\n"))).toBe(12);
        expect(skipChars(buf, 12, ds("dne"))).toBe(15);
    });

    test("unittest#2 replaceChar", () => {
        const r = (s: string): string => dsToJs(replaceChar(ds(s), 0x2c /* ',' */, ds("$(COMMA)")));
        expect(r("")).toBe("");
        expect(r("ab")).toBe("ab");
        expect(r("a,b")).toBe("a$(COMMA)b");
        expect(r("a,,b")).toBe("a$(COMMA)$(COMMA)b");
        expect(r(",ab")).toBe("$(COMMA)ab");
        expect(r("ab,")).toBe("ab$(COMMA)");
    });

    test("unittest#3 toLowercase", () => {
        const l = (s: string): string => dsToJs(toLowercase(ds(s)));
        expect(l("")).toBe("");
        expect(l("abc")).toBe("abc");
        expect(l("ABC")).toBe("abc");
        expect(l("aBc")).toBe("abc");
    });

    test("unittest#4 MarkdownLink.removeEscapeBackslashes", () => {
        const r = (s: string): string => dsToJs(MarkdownLink.removeEscapeBackslashes(ds(s)));   // `.dup`: ds copies
        expect(r("")).toBe("");
        expect(r("\\a")).toBe("\\a");
        expect(r(".\\")).toBe(".\\");
        expect(r("\\.\\")).toBe(".\\");
        expect(r("\\.")).toBe(".");
        expect(r("\\.\\.")).toBe("..");
        expect(r("a\\.b\\.c")).toBe("a.b.c");
    });

    test("unittest#5 MarkdownLink.percentEncode", () => {
        const e = (s: string): string => dsToJs(MarkdownLink.percentEncode(ds(s)));
        expect(e("")).toBe("");
        expect(e("aB12-._~/?")).toBe("aB12-._~/?");
        expect(e("<\n>")).toBe("%3C%0A%3E");
    });

    test("unittest#6 MarkdownLinkReferences.split", () => {
        const s = (str: string): string[] => MarkdownLinkReferences.split(ds(str), 0x2c /* ',' */).map(dsToJs);
        expect(s("")).toEqual([""]);
        expect(s("ab")).toEqual(["ab"]);
        expect(s("a,b")).toEqual(["a", "b"]);
        expect(s("a,,b")).toEqual(["a", "", "b"]);
        expect(s(",ab")).toEqual(["", "ab"]);
        expect(s("ab,")).toEqual(["ab", ""]);
    });
});

describe("the embedded theme (doc.d:950)", () => {
    test("default_ddoc_theme is dmd/res/default_ddoc_theme.ddoc byte for byte", () => {
        const file = readFileSync(join(LDC, "dmd/res/default_ddoc_theme.ddoc"));
        expect(Buffer.from(ds(default_ddoc_theme)).equals(file)).toBe(true);
    });
});

describe("escapeDdocString (doc.d:178)", () => {
    test("`$`, `(` and `)` from the start offset on become macros", () => {
        const buf = new OutBuffer();
        buf.writestring(ds("f($x) \"($)\""));
        escapeDdocString(buf, 5);
        expect(dsToJs(buf.opSliceAll())).toBe("f($x) \"$(LPAREN)$(DOLLAR)$(RPAREN)\"");
    });
});

describe("gendocfile through the shim, against ldc2's HTML", () => {
    const dir = mkdtempSync(join(tmpdir(), "djs-doc-"));
    afterAll(() => rmSync(dir, { recursive: true, force: true }));

    /** Run the shim (a fresh module registry, as main.test.ts does) and return its status and output. */
    async function shim(args: string[]): Promise<{ code: number; output: string }> {
        vi.resetModules();
        const { djsMain } = await import("../djs.js");
        const out: string[] = [];
        const dec = (c: string | Uint8Array): string => (typeof c === "string" ? c : new TextDecoder().decode(c));
        const tap = (c: string | Uint8Array): boolean => {
            out.push(dec(c));
            return true;
        };
        const o = vi.spyOn(process.stdout, "write").mockImplementation(tap);
        const e = vi.spyOn(process.stderr, "write").mockImplementation(tap);
        try {
            const code = djsMain(args);
            return { code, output: out.join("") };
        } finally {
            o.mockRestore();
            e.mockRestore();
        }
    }

    /** ddocAny-postscript.sh's normalization: no `Generated by Ddoc from` line, no line-ending CR. */
    const normalize = (text: string): string =>
        text.split("\n").filter((l) => !l.includes("Generated by Ddoc from")).map((l) => l.replace(/\r$/, ""))
            .join("\n");

    /** The expected page of `name`: extra-files/<name>.html, normalized, with the OUTPUT_FILES header line
     *  and the `__YEAR__` placeholder resolved as described in the file header. */
    const expected = (name: string): string => {
        let text = normalize(readFileSync(join(COMPILABLE, "extra-files", `${name}.html`), "latin1"));
        if (text.startsWith("=== "))
            text = text.slice(text.indexOf("\n"));   // the header stands where the leading blank line is
        return text.replace("__YEAR__", String(new Date().getFullYear()));
    };

    /** Compile `name` (plus `more` sources) with `-D` into a fresh directory; return the shim's page. */
    async function ddoc(name: string, flags: string[] = [], more: string[] = []): Promise<string> {
        const out = mkdtempSync(join(dir, `${name}-`));
        const r = await shim(["-m64", `-I${COMPILABLE}`, "-D", `-Dd${out}`, ...flags, "-o-", "-c",
            join(COMPILABLE, `${name}.d`), ...more]);
        expect(r.output).toBe("");
        expect(r.code).toBe(0);
        return normalize(readFileSync(join(out, `${name}.html`), "latin1"));
    }

    test("compilable/ddoc1.d (-d): sections, aliases, ditto, deprecated members", async () => {
        expect(await ddoc("ddoc1", ["-d"])).toBe(expected("ddoc1"));
    });

    test("compilable/ddoc10.d: overloads, templates, parameter tables", async () => {
        expect(await ddoc("ddoc10")).toBe(expected("ddoc10"));
    });

    test("compilable/ddoc_markdown_emphasis.d", async () => {
        expect(await ddoc("ddoc_markdown_emphasis")).toBe(expected("ddoc_markdown_emphasis"));
    });

    test("compilable/ddoc_markdown_lists.d", async () => {
        expect(await ddoc("ddoc_markdown_lists")).toBe(expected("ddoc_markdown_lists"));
    });

    test("compilable/ddoc_markdown_tables.d", async () => {
        expect(await ddoc("ddoc_markdown_tables")).toBe(expected("ddoc_markdown_tables"));
    });

    test("compilable/ddoc9369.d with extra-files/ddoc9369.ddoc: macros from a .ddoc file", async () => {
        expect(await ddoc("ddoc9369", [], [join(COMPILABLE, "extra-files", "ddoc9369.ddoc")]))
            .toBe(expected("ddoc9369"));
    });

    test("compilable/ddoc_bom_UTF8.d: a source starting with a byte-order mark", async () => {
        expect(await ddoc("ddoc_bom_UTF8")).toBe(expected("ddoc_bom_UTF8"));
    });

    test("compilable/ddocYear.d: $(YEAR) from the 26-byte datetime (doc.d:93)", async () => {
        expect(await ddoc("ddocYear")).toBe(expected("ddocYear"));
    });

    // doc.d:5068-5087 reserves `paramLens` and writes past its length, so the template parameter list is wrapped
    // in DDOC_TEMPLATE_PARAM_LIST and its parameters never in DDOC_TEMPLATE_PARAM (the declared divergence in the
    // doc.ts header). Oracle: ldmd2 -D -Dd<dir> -o- -c tp.d tp.ddoc, the two files below, CRs dropped.
    test("a templated function's parameter list: DDOC_TEMPLATE_PARAM_LIST only (doc.d:5097/:5108)", async () => {
        const src = mkdtempSync(join(dir, "tp-"));
        writeFileSync(join(src, "tp.d"), "module tp;\n/// doc\nvoid foo(T, U)(T a, U b) {}\n");
        writeFileSync(join(src, "tp.ddoc"),
            "DDOC = $(BODY)\nDDOC_TEMPLATE_PARAM_LIST = [LIST $0]\nDDOC_TEMPLATE_PARAM = [PARAM $0]\n");
        const r = await shim(["-D", `-Dd${src}`, "-o-", "-c", join(src, "tp.d"), join(src, "tp.ddoc")]);
        expect(r.output).toBe("");
        expect(r.code).toBe(0);
        expect(readFileSync(join(src, "tp.html"), "latin1").replace(/\r/g, "")).toBe([
            "",
            "<section class=\"section ddoc_module_members_section\">",
            "  <div class=\"ddoc_module_members\">",
            "    <ul class=\"ddoc_members\">",
            "  <li class=\"ddoc_member\">",
            "  <div class=\"ddoc_member_header\">",
            "  <div class=\"ddoc_header_anchor\">",
            "  <a href=\"#foo\" id=\"foo\"><code class=\"code\">foo</code></a>",
            "</div>",
            "</div><div class=\"ddoc_decl\">",
            "  <section class=\"section\">",
            "    <div class=\"declaration\">",
            "      <h4>Declaration</h4>",
            "      <div class=\"dlang\">",
            "        <p class=\"para\">",
            "          <code class=\"code\">",
            "            <span class=\"ddoc_anchor\" id=\"foo\"></span>void <code class=\"code\">foo</code>"
                + "[LIST (T, U)](T <code class=\"code\">a</code>, U <code class=\"code\">b</code>);",
            "",
            "          </code>",
            "        </p>",
            "      </div>",
            "    </div>",
            "  </section>",
            "</div>",
            "<div class=\"ddoc_decl\">",
            "  <section class=\"section ddoc_sections\">",
            "  <div class=\"ddoc_summary\">",
            "  <p class=\"para\">",
            "    doc",
            "  </p>",
            "</div>",
            "",
            "</section>",
            "",
            "</div>",
            "",
            "</li>",
            "</ul>",
            "  </div>",
            "</section>",
            "",
        ].join("\n"));
    });

    // Documented unittests print their bodies from `UnitTestDeclaration.codedoc` (doc.d:603), which the
    // parser fills only under `compileEnv.ddocOutput` (parse.d:2836-2855).
    test("compilable/ddocunittest.d (-w): documented unittests", async () => {
        expect(await ddoc("ddocunittest", ["-w"])).toBe(expected("ddocunittest"));
    });
});
